	var head struct {
		Version int `json:"version"`
	}
	err := json.Unmarshal(b, &head)
	return head.Version, err
}

// decode returns the state in a snapshot file of any version Load reads, and when the file was saved (zero for version 1,
// which did not record it). Invoices from versions 1 and 2 are numbered here.
func decode(b []byte) (store.State, time.Time, error) {
	v, err := versionOf(b)
	if err != nil {
		return store.State{}, time.Time{}, err
	}
	switch v {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return store.State{}, time.Time{}, fmt.Errorf("version 1: %w", err)
		}
		numberInvoices(&st)
		return st, time.Time{}, nil
	case 2, 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, time.Time{}, err
		}
		if v == 2 {
			numberInvoices(&f.State)
		}
		return f.State, f.SavedAt, nil
	default:
		return store.State{}, time.Time{}, fmt.Errorf("%w %d", ErrUnsupportedVersion, v)
	}
}

// numberInvoices gives the invoices of a file from before version 3 their numbers: per organization, in creation order
// (created_at, then ID). It also records each organization's next number.
func numberInvoices(st *store.State) {
	invs := make([]*store.Invoice, 0, len(st.Invoices))
	for i := range st.Invoices {
		invs = append(invs, &st.Invoices[i])
	}
	sort.Slice(invs, func(i, j int) bool {
		if !invs[i].CreatedAt.Equal(invs[j].CreatedAt) {
			return invs[i].CreatedAt.Before(invs[j].CreatedAt)
		}
		return invs[i].ID < invs[j].ID
	})
	next := map[string]int{}
	for _, inv := range invs {
		n := max(next[inv.OrgID], 1)
		inv.Number = store.InvoiceNumber(n)
		next[inv.OrgID] = n + 1
	}
	st.NextInvoiceNumbers = next
}

