// writeV2 writes st as a version 2 file, which has no invoice numbers, and returns the bytes written.
func writeV2(t *testing.T, path string, st *store.Store, savedAt time.Time) []byte {
	t.Helper()
	state := st.Export()
	for i := range state.Invoices {
		state.Invoices[i].Number = ""
	}
	state.NextInvoiceNumbers = nil
	b, err := json.MarshalIndent(fileV3{Version: 2, SavedAt: savedAt, State: state}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	b = append(b, '\n')
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
	return b
}

func TestLoadVersion2NumbersInvoicesInCreationOrder(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	a, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	b, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	ca, _ := st.CreateCustomer(a.ID, "Ann", "ann@example.com", now)
	cb, _ := st.CreateCustomer(b.ID, "Ben", "ben@example.com", now)
	line := []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}
	// Created in this order, so the IDs are in_000001, in_000002 and in_000003, but the creation times are not in ID order.
	for _, c := range []struct {
		org, cus string
		at       time.Time
	}{{a.ID, ca.ID, now.Add(3 * time.Hour)}, {a.ID, ca.ID, now.Add(1 * time.Hour)}, {a.ID, ca.ID, now.Add(2 * time.Hour)}, {b.ID, cb.ID, now}} {
		if _, err := st.CreateInvoice(store.Invoice{OrgID: c.org, CustomerID: c.cus, Currency: money.EUR, Lines: line}, c.at); err != nil {
			t.Fatal(err)
		}
	}

	path := filepath.Join(t.TempDir(), "tally.json")
	writeV2(t, path, st, now)
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	for id, want := range map[string]string{"in_000001": "INV-000003", "in_000002": "INV-000001", "in_000003": "INV-000002", "in_000004": "INV-000001"} {
		inv, ok := got.InvoiceByID(id)
		if !ok || inv.Number != want {
			t.Fatalf("invoice %s has number %q, want %q", id, inv.Number, want)
		}
	}
	next, err := got.CreateInvoice(store.Invoice{OrgID: a.ID, CustomerID: ca.ID, Currency: money.EUR, Lines: line}, now)
	if err != nil || next.Number != "INV-000004" {
		t.Fatalf("the next invoice has number %q: %v", next.Number, err)
	}
}

