		t.Fatal(err)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := versionOf(b); err != nil || v != 3 {
		t.Fatalf("saved version %d: %v", v, err)
