	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name() != "tally.json" {
		t.Fatalf("the folder holds %v after a save", entries)
	}
}

