	}
}

func TestUpgradeVersion1(t *testing.T) {
	orig, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	before, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	bak, err := os.ReadFile(path + ".v1.bak")
	if err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup is not the original file: %v", err)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := versionOf(b); err != nil || v != 3 {
		t.Fatalf("upgraded version %d: %v", v, err)
	}
	after, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(before.Export(), after.Export()) {
		t.Fatal("the upgraded store differs from the version 1 store")
	}
}

