func TestUpgradeLeavesVersion3Alone(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(store.New(), path, time.Now()); err != nil {
		t.Fatal(err)
	}
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	after, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(before, after) {
		t.Fatalf("a version 3 file changed: %v", err)
	}
	if _, err := os.Stat(path + ".v3.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a backup of a version 3 file was written: %v", err)
	}
}

func TestUpgradeRefusesNewerVersions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "future.json")
	orig := []byte(`{"version": 4, "state": {}}`)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	after, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(after, orig) {
		t.Fatalf("a newer file changed: %v", err)
	}
	if _, err := os.Stat(path + ".v4.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a backup of a newer file was written: %v", err)
	}
}

